import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminFCurso = () => {
  const [editMode, setEditMode] = useState(false);
  const [curso, setCurso] = useState({
    nome: "Contabilidade II",
    nivel: "2",
    periodo: "Manhã (09:00-11:00)",
    area: "Contabilidade",
    professor: "Paulo Carvalho",
    alunos: ["Ana Francisca", "Paula Ana", "Tiago Nunes", "Rafael Oliveira"],
  });

  const handleEditClick = () => {
    setEditMode(true);
  };

  const handleCancelClick = () => {
    setEditMode(false);
  };

  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  const handleAlunoChange = (index, value) => {
    const novosAlunos = [...curso.alunos];
    novosAlunos[index] = value;
    setCurso({ ...curso, alunos: novosAlunos });
  };

  const handleAddAluno = () => {
    setCurso({ ...curso, alunos: [...curso.alunos, ""] });
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary">EducaWeb</h1>
      <ul className="nav nav-tabs mt-3">
        <li className="nav-item">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="bg-white p-4 rounded shadow mt-3">
        <h4 className="fw-bold">informação do curso</h4>
        <p>
          <strong>{curso.nome}</strong>
        </p>
        <p>Nível: {curso.nivel}</p>
        <p>Período: {curso.periodo}</p>
        <p>Área: {curso.area}</p>

        {editMode && (
          <div className="mt-3">
            <div className="mb-3">
              <label className="fw-bold">Professor</label>
              <div className="input-group">
                <input
                  type="text"
                  className="form-control"
                  name="professor"
                  value={curso.professor}
                  onChange={handleChange}
                />
                <button className="btn btn-outline-secondary">+</button>
              </div>
            </div>

            <label className="fw-bold">Alunos</label>
            {curso.alunos.map((aluno, index) => (
              <input
                key={index}
                type="text"
                className="form-control mb-2"
                value={aluno}
                onChange={(e) => handleAlunoChange(index, e.target.value)}
              />
            ))}
            <button
              className="btn btn-outline-secondary mt-2"
              onClick={handleAddAluno}
            >
              +
            </button>

            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                cancelar
              </button>
              <button
                className="btn btn-primary"
                onClick={() => setEditMode(false)}
              >
                salvar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminFCurso;
